CREATE TABLE IF NOT EXISTS users (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, full_name VARCHAR(100) NOT NULL, email VARCHAR(150) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role VARCHAR(10) NOT NULL DEFAULT 'user' CHECK(role IN ('user','admin','coach')), status VARCHAR(12) NOT NULL DEFAULT 'active' CHECK(status IN ('active','suspended')), terms_accepted_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, last_login_at DATETIME, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS auth_sessions (id VARCHAR(64) PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, csrf_token VARCHAR(64) NOT NULL, expires_at DATETIME NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS profiles (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, user_id BIGINT UNSIGNED NOT NULL UNIQUE, goal VARCHAR(20) NOT NULL CHECK(goal IN ('build_muscle','lose_weight','general_fitness')), level VARCHAR(15) NOT NULL CHECK(level IN ('beginner','intermediate')), equipment_level VARCHAR(15) NOT NULL CHECK(equipment_level IN ('none','dumbbell','full_gym')), limitation_notes VARCHAR(200), session_minutes INTEGER NOT NULL CHECK(session_minutes IN (30,45,60)), plan_start_date DATE NOT NULL, onboarding_completed INTEGER NOT NULL DEFAULT 1, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS profile_days (profile_id BIGINT UNSIGNED NOT NULL, weekday INTEGER NOT NULL CHECK(weekday BETWEEN 1 AND 7), PRIMARY KEY(profile_id,weekday), FOREIGN KEY(profile_id) REFERENCES profiles(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS equipment_access (equipment_level VARCHAR(15) NOT NULL, equipment_type VARCHAR(15) NOT NULL, PRIMARY KEY(equipment_level,equipment_type)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS exercises (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, name VARCHAR(100) NOT NULL UNIQUE, muscle_group VARCHAR(15) NOT NULL CHECK(muscle_group IN ('chest','back','legs','shoulders','arms','core')), split_tag VARCHAR(10) NOT NULL CHECK(split_tag IN ('push','pull','legs','core')), movement_focus VARCHAR(10) NOT NULL DEFAULT 'none' CHECK(movement_focus IN ('squat','hinge','none')), equipment_type VARCHAR(15) NOT NULL CHECK(equipment_type IN ('bodyweight','dumbbell','barbell','machine','cable')), level VARCHAR(15) NOT NULL CHECK(level IN ('beginner','intermediate','advanced')), default_sets INTEGER NOT NULL CHECK(default_sets BETWEEN 1 AND 6), default_rep_min INTEGER NOT NULL CHECK(default_rep_min BETWEEN 1 AND 30), default_rep_max INTEGER NOT NULL CHECK(default_rep_max>=default_rep_min AND default_rep_max<=50), load_increment_kg DECIMAL(5,2) NOT NULL, base_load_beginner_kg DECIMAL(5,2), base_load_intermediate_kg DECIMAL(5,2), image_url VARCHAR(255), instructions TEXT, is_compound INTEGER NOT NULL DEFAULT 1, is_active INTEGER NOT NULL DEFAULT 1, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS exercise_limitation_tags (exercise_id BIGINT UNSIGNED NOT NULL, tag VARCHAR(12) NOT NULL CHECK(tag IN ('knee','back','shoulder','wrist','elbow','neck')), PRIMARY KEY(exercise_id,tag), FOREIGN KEY(exercise_id) REFERENCES exercises(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS plans (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, user_id BIGINT UNSIGNED NOT NULL, version INTEGER NOT NULL, status VARCHAR(10) NOT NULL CHECK(status IN ('active','archived')), split_type VARCHAR(15) NOT NULL, generated_by VARCHAR(20) NOT NULL, adjusted_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, adjustment_reason VARCHAR(255), locked_by_coach INTEGER NOT NULL DEFAULT 0, active_user_key BIGINT UNSIGNED GENERATED ALWAYS AS (CASE WHEN status='active' THEN user_id ELSE NULL END) STORED UNIQUE, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS planned_sessions (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, plan_id BIGINT UNSIGNED NOT NULL, scheduled_date DATE NOT NULL, original_date DATE, is_rest INTEGER NOT NULL DEFAULT 0, session_label VARCHAR(80), status VARCHAR(15) NOT NULL DEFAULT 'scheduled' CHECK(status IN ('scheduled','in_progress','completed','partial','missed','rescheduled')), carry_over_focus VARCHAR(10), volume_modifier DECIMAL(3,2) NOT NULL DEFAULT 1, UNIQUE(plan_id,scheduled_date), FOREIGN KEY(plan_id) REFERENCES plans(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS planned_exercises (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, planned_session_id BIGINT UNSIGNED NOT NULL, exercise_id BIGINT UNSIGNED NOT NULL, order_no INTEGER NOT NULL, target_sets INTEGER NOT NULL, target_rep_min INTEGER NOT NULL, target_rep_max INTEGER NOT NULL, target_weight_kg DECIMAL(5,2), UNIQUE(planned_session_id,order_no), FOREIGN KEY(planned_session_id) REFERENCES planned_sessions(id) ON DELETE CASCADE, FOREIGN KEY(exercise_id) REFERENCES exercises(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS session_logs (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, planned_session_id BIGINT UNSIGNED NOT NULL UNIQUE, user_id BIGINT UNSIGNED NOT NULL, started_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, ended_at DATETIME, status VARCHAR(15) NOT NULL DEFAULT 'in_progress', session_rpe DECIMAL(3,1), edit_locked_at DATETIME, FOREIGN KEY(planned_session_id) REFERENCES planned_sessions(id) ON DELETE CASCADE, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS exercise_logs (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, session_log_id BIGINT UNSIGNED NOT NULL, planned_exercise_id BIGINT UNSIGNED NOT NULL, exercise_id BIGINT UNSIGNED NOT NULL, status VARCHAR(15) NOT NULL DEFAULT 'missed', avg_rpe DECIMAL(3,1), top_weight_kg DECIMAL(5,2), notes VARCHAR(200), UNIQUE(session_log_id,planned_exercise_id), FOREIGN KEY(session_log_id) REFERENCES session_logs(id) ON DELETE CASCADE, FOREIGN KEY(planned_exercise_id) REFERENCES planned_exercises(id) ON DELETE CASCADE, FOREIGN KEY(exercise_id) REFERENCES exercises(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS set_logs (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, exercise_log_id BIGINT UNSIGNED NOT NULL, set_no INTEGER NOT NULL CHECK(set_no BETWEEN 1 AND 6), reps INTEGER NOT NULL CHECK(reps BETWEEN 1 AND 100), weight_kg DECIMAL(5,2) NOT NULL CHECK(weight_kg>=0), rpe INTEGER NOT NULL CHECK(rpe BETWEEN 1 AND 10), is_completed INTEGER NOT NULL DEFAULT 1, UNIQUE(exercise_log_id,set_no), FOREIGN KEY(exercise_log_id) REFERENCES exercise_logs(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS adaptation_events (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, user_id BIGINT UNSIGNED NOT NULL, plan_id BIGINT UNSIGNED NOT NULL, exercise_id BIGINT UNSIGNED, source_key VARCHAR(100) UNIQUE, rule_code VARCHAR(10) NOT NULL, action VARCHAR(30) NOT NULL, old_value VARCHAR(50), new_value VARCHAR(50), reason_text VARCHAR(255) NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(plan_id) REFERENCES plans(id) ON DELETE CASCADE, FOREIGN KEY(exercise_id) REFERENCES exercises(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS feedback_responses (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, user_id BIGINT UNSIGNED NOT NULL, ease_score INTEGER NOT NULL CHECK(ease_score BETWEEN 1 AND 5), clarity_score INTEGER NOT NULL CHECK(clarity_score BETWEEN 1 AND 5), adjustment_score INTEGER NOT NULL CHECK(adjustment_score BETWEEN 1 AND 5), comments TEXT, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS notifications (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, user_id BIGINT UNSIGNED NOT NULL, type VARCHAR(20) NOT NULL, message VARCHAR(255) NOT NULL, is_read INTEGER NOT NULL DEFAULT 0, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS audit_logs (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, actor_user_id BIGINT UNSIGNED, action VARCHAR(50) NOT NULL, target_type VARCHAR(30) NOT NULL, target_id BIGINT UNSIGNED, meta_json JSON, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(actor_user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS coach_clients (coach_id BIGINT UNSIGNED NOT NULL, client_id BIGINT UNSIGNED NOT NULL, assigned_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(coach_id,client_id), FOREIGN KEY(coach_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(client_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS coach_notes (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, coach_id BIGINT UNSIGNED NOT NULL, client_id BIGINT UNSIGNED NOT NULL, message TEXT NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(coach_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(client_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;